        return grid

    # Find object (non-bg, non-frame)
    obj_cells = [(r, c, grid[r][c]) for r in range(len(grid)) for c in range(len(grid[0])) 
                 if grid[r][c] != bg and grid[r][c] != frame_color]
    if not obj_cells:
        return grid

    ormin, ormax = min(x[0] for x in obj_cells), max(x[0] for x in obj_cells)
    ocmin, ocmax = min(x[1] for x in obj_cells), max(x[1] for x in obj_cells)

    # Result grid
    result = [row[:] for row in grid]

    # Clear original object location
    for r in range(ormin, ormax + 1):
        for c in range(ocmin, ocmax + 1):
            result[r][c] = bg

    # Fill hole with object
    hole_rmin = frame_rmin + 1
    hole_cmin = frame_cmin + 1

    for dr in range(ormax - ormin + 1):
        for dc in range(ocmax - ocmin + 1):
