def transform(grid):
    if not grid or not grid[0]:
        return grid

    # Background is most frequent
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Find the 6-frame (it's always color 6 in this task)
    frame_pixels = [(r, c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] == 6]
    if not frame_pixels:
        return grid

    frame_rmin, frame_rmax = min(x[0] for x in frame_pixels), max(x[0] for x in frame_pixels)
    frame_cmin, frame_cmax = min(x[1] for x in frame_pixels), max(x[1] for x in frame_pixels)

    # Find object cells (non-bg, non-6)
    obj_cells = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != bg and grid[r][c] != 6:
                obj_cells.append((r, c, grid[r][c]))
    if not obj_cells:
        return grid

    # Object bounding box
    ormin, ormax = min(x[0] for x in obj_cells), max(x[0] for x in obj_cells)
    ocmin, ocmax = min(x[1] for x in obj_cells), max(x[1] for x in obj_cells)

    # Create result as copy
    result = [row[:] for row in grid]

    # Fill original object location with bg
    for r in range(ormin, ormax + 1):
        for c in range(ocmin, ocmax + 1):
            result[r][c] = bg

    # Fill frame hole with object content
    hole_rmin = frame_rmin + 1
    hole_cmin = frame_cmin + 1

    for r in range(ormin, ormax + 1):
        for c in range(ocmin, ocmax + 1):
            dr = r - ormin
            dc = c - ocmin
            dst_r = hole_rmin + dr
            dst_c = hole_cmin + dc
            if 0 <= dst_r < len(result) and 0 <= dst_c < len(result[0]):
                result[dst_r][dst_c] = grid[r][c]

    return result
